// @ts-check

import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

import {themes as prismThemes} from 'prism-react-renderer';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Licensed-source count for the homepage proof strip and the research page —
// read at BUILD TIME from the license register rollup so the displayed number
// can never drift from shared/licenses.json (regenerated by
// mt-eval-arena/scripts/build-shared-licenses.mjs). Same root-SSOT-first,
// bundled-copy-fallback resolution as plugins/shared-data. FAIL LOUD: a
// missing or malformed register must break the build, never render a stale
// or invented count.
const licensesJsonPath = [
  path.resolve(__dirname, '..', '..', 'shared', 'licenses.json'),
  path.resolve(__dirname, '..', 'shared', 'licenses.json'),
].find((p) => fs.existsSync(p));
if (!licensesJsonPath) {
  throw new Error(
    '[docusaurus.config] shared/licenses.json not found (repo root or cli/shared) — cannot resolve the licensed-source count.',
  );
}
const licensesRegister = JSON.parse(fs.readFileSync(licensesJsonPath, 'utf8'));
const licensedSourceCount = licensesRegister?._generated?.counts?.total;
const licensedSourceDate = String(licensesRegister?._generated?.generatedAt || '').slice(0, 10);
if (!Number.isInteger(licensedSourceCount) || licensedSourceCount <= 0 || !/^\d{4}-\d{2}-\d{2}$/.test(licensedSourceDate)) {
  throw new Error(
    `[docusaurus.config] ${licensesJsonPath} has no valid _generated.counts.total / _generated.generatedAt — refusing to build with an unknown licensed-source count.`,
  );
}

// Dataset-registry count for /research and the who-benefits page — read at
// BUILD TIME from the corpora SSOT (arena/datasets/registry.json). Falls back
// to static/registry.json, the verbatim copy ensure-network-artifacts stages
// at prebuild, so cli/website-only deploys still resolve it. FAIL LOUD.
const registryJsonPath = [
  path.resolve(__dirname, '..', '..', 'arena', 'datasets', 'registry.json'),
  path.resolve(__dirname, 'static', 'registry.json'),
].find((p) => fs.existsSync(p));
if (!registryJsonPath) {
  throw new Error(
    '[docusaurus.config] dataset registry not found (arena/datasets/registry.json or static/registry.json) — cannot resolve the dataset count.',
  );
}
const registryDatasetCount = JSON.parse(fs.readFileSync(registryJsonPath, 'utf8'))?.datasets?.length;
if (!Number.isInteger(registryDatasetCount) || registryDatasetCount <= 0) {
  throw new Error(
    `[docusaurus.config] ${registryJsonPath} has no datasets[] — refusing to build with an unknown dataset count.`,
  );
}

// Catalogue size = the language-card SSOT: one card file per catalogued
// language (language-tree.json is layout metadata, not a card). The same
// gate build-trading-card-data.mjs uses, so this count equals the published
// trading-card index by construction.
const cardsDir = path.resolve(__dirname, '..', 'shared', 'language-cards');
if (!fs.existsSync(cardsDir)) {
  throw new Error(
    `[docusaurus.config] language-card SSOT not found at ${cardsDir} — cannot resolve the catalogue count.`,
  );
}
// LANGUAGES, NOT CARD FILES.
//
// The corpus now also holds 8,675 LOCALE cards — `fra-CA` is French as spoken
// in Canada, a projection of French, not a second language. Counting files
// gave 17,360 and this number is rendered by <SSOTCount> on six public pages,
// so the site would have claimed roughly twice the languages it indexes, with
// French counted once per territory it is spoken in.
//
// A locale names its parent in `locale.language`; that is the discriminator,
// never the shape of the code. cli/scripts/check-prose-counts-parity.mjs
// filters the same way — the two agreed on the rule and disagreed on the
// number, and the parity gate could not catch it because this value reaches
// the page through a component rather than as literal prose.
const catalogLanguageCount = fs
  .readdirSync(cardsDir)
  .filter((f) => f.endsWith('.json') && f !== 'language-tree.json')
  .filter((f) => {
    try {
      const c = JSON.parse(fs.readFileSync(path.join(cardsDir, f), 'utf-8'));
      return !c?.locale?.language;
    } catch {
      // An unreadable card is counted rather than silently dropped; the card
      // linter is what reports it, and swallowing it here would shrink a
      // public number for a reason nobody could see.
      return true;
    }
  }).length;
if (catalogLanguageCount <= 0) {
  throw new Error(
    `[docusaurus.config] language-card SSOT at ${cardsDir} is empty — refusing to build with an unknown catalogue count.`,
  );
}

